def replace(version, **parts):
    """Return a version string with the supplied components replaced.

    The version is parsed before replacement, and unspecified components are
    retained. The accepted keywords are major, minor, patch, prerelease and
    build. Use ``None`` to remove prerelease or build metadata.

    >>> replace('1.2.3-rc.1+build.2', patch=4, build=None)
    '1.2.4-rc.1'
    """
    return str(parse_version_info(version).replace(**parts))


